import{_ as t}from"./chunks/flaky-detection.CN9mtzEz.js";import{_ as a,o,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Cut the flakiness that costs the most","description":"","frontmatter":{"title":"Cut the flakiness that costs the most","lang":"en-US"},"headers":[],"relativePath":"recipes/flaky-cleanup.md","filePath":"recipes/flaky-cleanup.md","lastUpdated":1788537413000}'),n={name:"recipes/flaky-cleanup.md"};function i(l,e,d,c,h,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="our-suite-is-unreliable-and-i-have-one-afternoon" tabindex="-1">Our suite is unreliable and I have one afternoon <a class="header-anchor" href="#our-suite-is-unreliable-and-i-have-one-afternoon" aria-label="Permalink to &quot;Our suite is unreliable and I have one afternoon&quot;">​</a></h1><p>Flaky-test cleanup usually stalls for the same reason: the list is long, every entry looks equally annoying, and there&#39;s no obvious first move. Ranking by flakiness score doesn&#39;t help much either — a test that flakes constantly but finishes in 200 ms costs almost nothing.</p><p>Rank by what it <em>costs</em> instead, fix three, and leave the rest running.</p><h2 id="_1-sort-by-impact-not-by-score" tabindex="-1">1. Sort by impact, not by score <a class="header-anchor" href="#_1-sort-by-impact-not-by-score" aria-label="Permalink to &quot;1. Sort by impact, not by score&quot;">​</a></h2><p>The <strong>Flaky tests</strong> tab scores each test from three signals — retry passes, status alternation, and overall failure rate — then ranks by <strong>impact</strong>: wasted CI minutes (retries × average failed duration) and pipeline-block effect.</p><figure><img src="'+t+'" alt="Flaky tests tab listing tests with impact, composite score, failure rate, retry passes, flip counts and root cause, above root-cause filter chips and a lookback selector"><figcaption>The Flaky tests tab — sortable by impact or score, filterable by root cause, over a lookback window you choose.</figcaption></figure><p>Sort by <strong>Impact</strong> and work down. The column carries a color-coded dot for wasted CI minutes — green under 5, amber under 30, red at 30 or more — and in a suite carrying real flake debt a few red rows usually account for most of the total.</p><h2 id="_2-filter-by-root-cause-and-fix-a-class-at-once" tabindex="-1">2. Filter by root cause and fix a class at once <a class="header-anchor" href="#_2-filter-by-root-cause-and-fix-a-class-at-once" aria-label="Permalink to &quot;2. Filter by root cause and fix a class at once&quot;">​</a></h2><p>Every flaky test is tagged with one of five categories from heuristics over its errors, steps, and browser spread:</p><table tabindex="0"><thead><tr><th>Category</th><th>Typical signals</th><th>Usually fixed by</th></tr></thead><tbody><tr><td><code>timing</code></td><td>Timeouts, &quot;to be visible&quot;, <code>waitFor</code></td><td>Replacing a sleep with a real wait condition</td></tr><tr><td><code>network</code></td><td><code>net::</code> / <code>ERR_</code> errors, 5xx, <code>ECONNREFUSED</code></td><td>Stubbing, or a retry on the fixture rather than the test</td></tr><tr><td><code>assertion</code></td><td><code>expect(...)</code>, snapshot comparison, no timing noise</td><td>A tolerance, or a genuinely wrong expectation</td></tr><tr><td><code>environment</code></td><td>Fails on exactly one browser while others pass</td><td>A browser-specific guard or a real compatibility bug</td></tr><tr><td><code>other</code></td><td>No clear signal</td><td>Reading it</td></tr></tbody></table><p>Filtering by category is the trick that makes an afternoon enough: eight <code>timing</code> flakes usually share one bad wait helper.</p><h2 id="_3-narrow-the-window-before-you-conclude-anything" tabindex="-1">3. Narrow the window before you conclude anything <a class="header-anchor" href="#_3-narrow-the-window-before-you-conclude-anything" aria-label="Permalink to &quot;3. Narrow the window before you conclude anything&quot;">​</a></h2><p>Two filters change the answer, and both are worth setting deliberately:</p><ul><li><strong>Lookback window</strong> — recent behavior or a longer baseline. A test fixed last week still looks awful over 90 days.</li><li><strong>Environment</strong> — select one environment and the analysis is scoped to its runs, so <code>staging</code> noise doesn&#39;t inflate a test that&#39;s stable in <code>production</code>. Set it via the reporter&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>.</li></ul><h2 id="_4-quarantine-the-rest-—-with-an-exit" tabindex="-1">4. Quarantine the rest — with an exit <a class="header-anchor" href="#_4-quarantine-the-rest-—-with-an-exit" aria-label="Permalink to &quot;4. Quarantine the rest — with an exit&quot;">​</a></h2><p>You will not fix them all today, and disabling them is how suites rot. The usual <code>--grep-invert @quarantine</code> approach stops the test running, so nothing ever proves it recovered and the list only grows.</p><p><a href="./../flaky-tests.html#quarantine-with-a-way-out">Quarantine in Piwi</a> keeps the test running and reporting. It is excluded from the <a href="./../ci.html#blocking-a-merge">CI gate</a>&#39;s verdict and nothing else:</p><ul><li>Passing runs accumulate as a <strong>streak</strong>; one failure resets it.</li><li>After five consecutive passes the test is flagged <strong>ready to release</strong> — you&#39;re told, not asked.</li><li><strong>Candidates</strong> are proposed from the flaky analysis, ranked by wasted CI minutes.</li><li><strong>Debt</strong> is reported in aggregate: how many are in, how many are ready to leave, how long the oldest has been there.</li></ul><p>The gate always states how many failures quarantine excluded, and <code>--max-quarantined</code> caps the list so it can&#39;t grow unbounded.</p><h2 id="_5-check-the-fix-held" tabindex="-1">5. Check the fix held <a class="header-anchor" href="#_5-check-the-fix-held" aria-label="Permalink to &quot;5. Check the fix held&quot;">​</a></h2><p>A flaky fix is easy to believe and hard to confirm. Each test case has a <strong>stability trend</strong> — pass rate, flaky rate, and average duration bucketed over time — which is the honest answer to &quot;did that help?&quot;. If the suite-wide picture is what you need, <a href="./../analytics.html">Analytics</a> lifts the same signals across every project, including wasted CI minutes and a global flaky leaderboard.</p><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in&quot;">​</a></h2><p><strong>Ask your agent.</strong> <code>list_flaky_tests</code> over the <a href="./../mcp.html">MCP server</a> returns the scores, impact ranking, and root-cause category; <code>get_test_stability_trend</code> answers whether one test is getting worse. Useful for &quot;what should I fix this sprint?&quot; without opening a browser.</p><p><strong>Script it.</strong> Quarantine is a REST resource — <code>GET</code>/<code>POST /api/projects/:id/quarantine</code> and <code>DELETE /api/projects/:id/quarantine/:testCaseId</code> — so promoting candidates or releasing ready tests can be a scheduled job. Shapes are in the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><p><strong>No server at all.</strong> If this is your own laptop suite rather than a team&#39;s, the <a href="./../desktop.html">desktop app</a> runs the same analysis with no Docker and no Node — Windows x64 and Apple-silicon macOS only, and the installers aren&#39;t signed yet.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../flaky-tests.html">Flaky tests</a> — the full scoring, quarantine, and performance reference</li><li><a href="./../analytics.html">Analytics</a> — the same signals across every project</li><li><a href="./regression-or-flaky.html">Regression or flake?</a> — deciding whether one red test belongs on this list</li></ul>',27)])])}const y=a(n,[["render",i]]);export{g as __pageData,y as default};
